/**
 * Storage abstraction for uploaded files (D-010; ARCHITECTURE.md: "Validated, renamed, stored
 * through `StorageProvider`"). The MVP has one adapter, the local disk; an S3-compatible adapter
 * can replace it behind the same interface (KNOWN_LIMITATIONS.md).
 *
 * Rules every adapter keeps:
 *
 *   - a key is generated by the server and matches STORAGE_KEY_PATTERN; an adapter refuses any
 *     other key with a TypeError (a programming error, never a client error), so no request value
 *     is ever joined into a path or an object name (TM-18);
 *   - an object is written once and never overwritten (section 5.8: "its bytes are never
 *     overwritten and its key is never reused"); writing an existing key fails;
 *   - `get` of a key with no object is null, never an error.
 */
import { randomBytes } from "node:crypto";
import { createReadStream } from "node:fs";
import { mkdir, stat, unlink, writeFile } from "node:fs/promises";
import { isAbsolute, join, resolve, sep } from "node:path";
import { Readable } from "node:stream";

import { STORAGE_KEY_PATTERN, STORAGE_KEY_RANDOM_BYTES } from "./schema";

export interface StoredObject {
  /** The object's bytes as a stream. */
  body: ReadableStream<Uint8Array>;
  /** Its length in bytes. */
  sizeBytes: number;
}

export interface StorageProvider {
  /** Stores `bytes` under `key`. Fails when an object with that key exists. */
  put(key: string, bytes: Uint8Array): Promise<void>;
  /** The object under `key`, or null when there is none. */
  get(key: string): Promise<StoredObject | null>;
  /** Removes the object under `key`; no object is not an error. */
  delete(key: string): Promise<void>;
}

/** A new storage key: 128 random bits as 32 lower-case hexadecimal digits. */
export function generateStorageKey(): string {
  return randomBytes(STORAGE_KEY_RANDOM_BYTES).toString("hex");
}

function assertKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) {
    throw new TypeError("StorageProvider: the key does not match the storage key pattern.");
  }
}

function isMissingFile(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    ((error as { code?: unknown }).code === "ENOENT" ||
      (error as { code?: unknown }).code === "ENOTDIR")
  );
}

function isExistingFile(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    (error as { code?: unknown }).code === "EEXIST"
  );
}

/**
 * Files under one root directory, two levels: `<root>/<first two digits of the key>/<key>`, so no
 * directory holds more than a 256th of the files. The path is built only from a key that matched
 * the pattern, and the result is checked to lie inside the root all the same.
 *
 * A file is written with the exclusive flag (`wx`): an existing file is never overwritten. A
 * write that fails half way can leave a partial file; such a file has no `Upload` row and is never
 * served (section 5.8), and the service deletes it.
 */
export class LocalDiskStorage implements StorageProvider {
  readonly root: string;

  constructor(root: string) {
    if (root.length === 0 || !isAbsolute(root)) {
      throw new TypeError("LocalDiskStorage: the root must be an absolute path.");
    }
    this.root = resolve(root);
  }

  private pathOf(key: string): { directory: string; file: string } {
    assertKey(key);
    const directory = join(this.root, key.slice(0, 2));
    const file = join(directory, key);
    if (!file.startsWith(this.root + sep)) {
      throw new TypeError("LocalDiskStorage: the path left the storage root.");
    }
    return { directory, file };
  }

  async put(key: string, bytes: Uint8Array): Promise<void> {
    const { directory, file } = this.pathOf(key);
    await mkdir(directory, { recursive: true });
    try {
      await writeFile(file, bytes, { flag: "wx" });
    } catch (error) {
      // A write that failed half way leaves a partial file of this key, which is removed. An
      // existing file (EEXIST) is someone else's and is never touched.
      if (!isExistingFile(error)) await unlink(file).catch(() => undefined);
      throw error;
    }
  }

  async get(key: string): Promise<StoredObject | null> {
    const { file } = this.pathOf(key);
    let sizeBytes: number;
    try {
      const info = await stat(file);
      if (!info.isFile()) return null;
      sizeBytes = info.size;
    } catch (error) {
      if (isMissingFile(error)) return null;
      throw error;
    }
    const body = Readable.toWeb(createReadStream(file)) as ReadableStream<Uint8Array>;
    return { body, sizeBytes };
  }

  async delete(key: string): Promise<void> {
    const { file } = this.pathOf(key);
    try {
      await unlink(file);
    } catch (error) {
      if (!isMissingFile(error)) throw error;
    }
  }
}
